/// glibc's TIS-620 (localedata/charmaps/TIS-620) and Apple's, from the standard's windows-874.
pub const tis_620: Legacy = .{ .encoding = .windows_874, .decode = &.{
    .{ .len = 1, .first = 0x80, .last = 0xa0 },
} };

/// glibc's IBM874 (localedata/charmaps/IBM874) and Apple's, from the standard's windows-874.
pub const ibm874: Legacy = .{ .encoding = .windows_874, .decode = &.{
    .{ .len = 1, .first = 0x81, .last = 0x84 },
    .{ .len = 1, .first = 0x86, .last = 0x90 },
    .{ .len = 1, .first = 0x98, .last = 0x9f },
} };

